sp_widget.client_script:
api.controller=function($scope, $window) {

    var c = this;


    /*
     * =====================================================
     * GO BACK TO RECRUITER DASHBOARD
     * =====================================================
     */

    c.goBack = function() {

        $window.location.href =
            "?id=recruiter_dashboard";

    };


    /*
     * =====================================================
     * OPEN CANDIDATE DETAILS
     * =====================================================
     */

    c.viewCandidate = function(sysId) {

        if (!sysId) {
            return;
        }


        $window.location.href =
            "?id=campus360_recruiter_candidate_details" +
            "&sys_id=" +
            encodeURIComponent(sysId);

    };

}

sp_widget.css:
.candidates-page {
    background: #f6f8fc;
    min-height: 100vh;
    padding: 30px;
    font-family: Arial, sans-serif;
}


/* =========================
   HEADER
========================= */

.page-header {
    background: #ffffff;
    border: 1px solid #e1e6f0;
    border-radius: 14px;
    padding: 25px 28px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 20px;
}

.eyebrow {
    color: #5368d8;
    font-size: 11px;
    font-weight: bold;
    letter-spacing: 1.5px;
    margin-bottom: 6px;
}

.page-header h1 {
    margin: 0;
    color: #14213d;
    font-size: 28px;
}

.page-header p {
    margin: 7px 0 0;
    color: #78839a;
    font-size: 13px;
}


/* =========================
   BACK BUTTON
========================= */

.back-btn {
    background: #ffffff;
    border: 1px solid #5368d8;
    color: #5368d8;

    padding: 10px 18px;
    border-radius: 8px;

    cursor: pointer;
    font-size: 13px;
}

.back-btn:hover {
    background: #5368d8;
    color: #ffffff;
}


/* =========================
   SEARCH
========================= */

.search-card {
    background: #ffffff;
    border: 1px solid #e1e6f0;
    border-radius: 14px;

    padding: 16px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 20px;
}

.search-box {
    width: 55%;

    display: flex;
    align-items: center;

    border: 1px solid #dce2ed;
    border-radius: 8px;

    padding: 0 12px;

    background: #ffffff;
}

.search-box span {
    color: #5368d8;
    font-size: 18px;
    margin-right: 8px;
}

.search-box input {
    width: 100%;
    border: none;
    outline: none;

    padding: 11px 5px;

    color: #29344e;
    font-size: 13px;
}

.candidate-count {
    color: #66728b;
    font-size: 13px;
}


/* =========================
   MAIN PANEL
========================= */

.candidate-panel {
    background: #ffffff;
    border: 1px solid #e1e6f0;
    border-radius: 14px;

    overflow: hidden;
}

.panel-header {
    padding: 22px 25px;
    border-bottom: 1px solid #edf0f5;
}

.panel-header h2 {
    margin: 0;
    color: #17213a;
    font-size: 20px;
}


/* =========================
   TABLE
========================= */

.candidate-table {
    display: grid;

    grid-template-columns:
        1.5fr
        1.4fr
        1.3fr
        1.1fr
        1.2fr
        0.7fr;

    align-items: center;

    column-gap: 15px;

    padding: 15px 25px;
}

.header-row {
    background: #fafbfe;

    color: #8993a8;

    font-size: 11px;
    font-weight: bold;

    text-transform: uppercase;
}

.candidate-row {
    border-top: 1px solid #edf0f5;
}

.candidate-row:hover {
    background: #fbfcff;
}


/* =========================
   CANDIDATE
========================= */

.candidate-info {
    display: flex;
    align-items: center;
    gap: 10px;
}

.avatar {
    width: 36px;
    height: 36px;

    border-radius: 50%;

    background: #edf0ff;
    color: #5368d8;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 12px;
    font-weight: bold;

    flex-shrink: 0;
}

.candidate-info strong {
    display: block;

    color: #17213a;
    font-size: 13px;

    margin-bottom: 3px;
}

.candidate-info span {
    display: block;

    color: #8a94a7;
    font-size: 10px;
}


/* =========================
   ROLE
========================= */

.role {
    color: #34405b;
    font-size: 13px;
}


/* =========================
   MATCH
========================= */

.match-container {
    display: flex;
    align-items: center;
    gap: 8px;
}

.match-bar {
    width: 65px;
    height: 6px;

    background: #e9edf7;
    border-radius: 10px;

    overflow: hidden;
}

.match-progress {
    height: 100%;
    background: #5368d8;

    border-radius: 10px;
}

.match-container span {
    color: #5368d8;
    font-size: 12px;
    font-weight: bold;
}


/* =========================
   STATUS
========================= */

.status {
    display: inline-block;

    padding: 5px 9px;

    border-radius: 7px;

    font-size: 10px;

    text-transform: capitalize;
}

.status-success {
    background: #e8f8ef;
    color: #218653;
}

.status-warning {
    background: #fff5dc;
    color: #a86b00;
}

.status-danger {
    background: #ffe9eb;
    color: #c93643;
}

.status-info {
    background: #eef1ff;
    color: #5368d8;
}


/* =========================
   STAGE
========================= */

.stage {
    color: #5f6a82;
    font-size: 12px;
}


/* =========================
   VIEW BUTTON
========================= */

.view-btn {
    border: none;

    background: #e9edff;
    color: #5368d8;

    padding: 7px 13px;

    border-radius: 6px;

    cursor: pointer;

    font-size: 11px;
}

.view-btn:hover {
    background: #5368d8;
    color: #ffffff;
}


/* =========================
   EMPTY
========================= */

.empty-state {
    padding: 60px 20px;
    text-align: center;
}

.empty-state h3 {
    color: #29344e;
    margin-bottom: 8px;
}

.empty-state p {
    color: #929bad;
    font-size: 13px;
}


/* =========================
   RESPONSIVE
========================= */

@media (max-width: 1000px) {

    .candidate-table {
        grid-template-columns:
            1.5fr
            1.2fr
            1fr
            1fr
            0.8fr;
    }

    .candidate-table > div:nth-child(5) {
        display: none;
    }

}


@media (max-width: 700px) {

    .candidates-page {
        padding: 15px;
    }

    .page-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 15px;
    }

    .search-card {
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
    }

    .search-box {
        width: 100%;
    }

    .candidate-panel {
        overflow-x: auto;
    }

    .candidate-table {
        min-width: 850px;
    }

}

sp_widget.script:
(function() {

    data.candidates = [];


    /*
     * =====================================================
     * GET APPLICATIONS
     * =====================================================
     */

    var applicationGR = new GlideRecord(
        "x_snc_campus360_student_application"
    );

    applicationGR.orderByDesc("sys_created_on");
    applicationGR.query();


    /*
     * =====================================================
     * BUILD CANDIDATE LIST
     * =====================================================
     */

    while (applicationGR.next()) {

        var studentSysId =
            applicationGR.getValue("student");

        if (!studentSysId) {
            continue;
        }


        /*
         * LOAD STUDENT
         */

        var studentGR = new GlideRecord(
            "x_snc_campus360_student_master"
        );

        if (!studentGR.get(studentSysId)) {
            continue;
        }


        var studentName =
            studentGR.getValue("student_name") || "Unknown";


        /*
         * MATCH SCORE
         */

        var matchScore =
            parseInt(
                applicationGR.getValue("ai_match_score"),
                10
            );

        if (isNaN(matchScore)) {
            matchScore = 0;
        }


        /*
         * STATUS
         */

        var status =
            applicationGR.getDisplayValue(
                "application_status"
            ) || "Pending";


        /*
         * STAGE
         *
         * Use application status as fallback because
         * the existing application structure already
         * provides this information.
         */

        var stage = status;


        /*
         * PUSH DATA
         */

        data.candidates.push({

            sys_id:
                studentGR.getUniqueValue(),

            name:
                studentName,

            initials:
                getInitials(studentName),

            student_id:
                studentGR.getValue("student_id") || "",

            role:
                applicationGR.getDisplayValue(
                    "opportunity"
                ) || "Not specified",

            match_score:
                matchScore,

            status:
                status,

            stage:
                stage

        });

    }


    /*
     * =====================================================
     * INITIALS FUNCTION
     * =====================================================
     */

    function getInitials(name) {

        if (!name) {
            return "ST";
        }

        var parts =
            name.trim().split(/\s+/);


        if (parts.length == 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    }

})();
